-- Expense Manager v3 — shared spaces sync API
-- MySQL 5.7+ / MariaDB 10.3+, utf8mb4. Idempotent (CREATE TABLE IF NOT EXISTS).
-- Import in phpMyAdmin (select the database first) or: mysql -u USER -p DBNAME < schema.sql
--
-- Conventions
--   * ids for users/spaces/synced rows are CHAR(36) uuids (synced rows are generated by the app).
--   * Sync tables (sp_*) carry: created_by, updated_by, updated_at (ms, server-assigned),
--     client_updated_at (ms), version, deleted (tombstone). Delta sync reads by (space_id, updated_at).
--   * JSON payloads are stored as LONGTEXT so the schema also works on hosts without a JSON type.
--   * DATETIME columns are UTC.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id                CHAR(36)      NOT NULL,
  email             VARCHAR(255)  NULL,
  apple_sub         VARCHAR(255)  NULL,
  google_sub        VARCHAR(255)  NULL,
  name              VARCHAR(80)   NOT NULL DEFAULT 'User',
  avatar_color      VARCHAR(16)   NULL,
  currency          CHAR(3)       NOT NULL DEFAULT 'USD',
  status            ENUM('active','deleted') NOT NULL DEFAULT 'active',
  token_valid_after DATETIME      NULL,              -- tokens issued before this are rejected (forced logout)
  created_at        DATETIME      NOT NULL,
  updated_at        DATETIME      NOT NULL,
  last_login_at     DATETIME      NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_apple (apple_sub),
  UNIQUE KEY uq_users_google (google_sub),
  KEY ix_users_email (email),
  KEY ix_users_created (created_at),
  KEY ix_users_last_login (last_login_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS devices (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     CHAR(36)      NOT NULL,
  device_id   VARCHAR(64)   NULL,                    -- app-generated stable id (identifierForVendor etc.)
  platform    ENUM('ios','android','web') NOT NULL DEFAULT 'ios',
  push_token  VARCHAR(512)  NULL,                    -- APNs hex token / FCM token
  app_version VARCHAR(32)   NULL,
  locale      VARCHAR(16)   NULL,
  created_at  DATETIME      NOT NULL,
  updated_at  DATETIME      NOT NULL,
  PRIMARY KEY (id),
  KEY ix_devices_user (user_id),
  KEY ix_devices_device (user_id, device_id),
  KEY ix_devices_token (push_token(191))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS otp_codes (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  email      VARCHAR(255)  NOT NULL,
  code_hash  CHAR(64)      NOT NULL,                 -- HMAC-SHA256(email|code, jwt_secret)
  expires_at DATETIME      NOT NULL,
  attempts   TINYINT UNSIGNED NOT NULL DEFAULT 0,
  used       TINYINT(1)    NOT NULL DEFAULT 0,
  ip         VARCHAR(45)   NULL,
  created_at DATETIME      NOT NULL,
  PRIMARY KEY (id),
  KEY ix_otp_email (email, used, id),
  KEY ix_otp_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Spaces, members, invites
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS spaces (
  id         CHAR(36)     NOT NULL,
  name       VARCHAR(80)  NOT NULL,
  type       ENUM('family','trip','flatmates','office','project','other') NOT NULL DEFAULT 'other',
  currency   CHAR(3)      NOT NULL DEFAULT 'USD',
  icon       VARCHAR(64)  NULL,
  color      VARCHAR(16)  NULL,
  share_mode ENUM('tagged','all') NOT NULL DEFAULT 'tagged',
  owner_id   CHAR(36)     NOT NULL,
  archived   TINYINT(1)   NOT NULL DEFAULT 0,
  created_at BIGINT       NOT NULL,                  -- ms
  updated_at BIGINT       NOT NULL,                  -- ms, bumped on any change inside the space
  PRIMARY KEY (id),
  KEY ix_spaces_owner (owner_id),
  KEY ix_spaces_updated (updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS space_members (
  space_id  CHAR(36) NOT NULL,
  user_id   CHAR(36) NOT NULL,
  role      ENUM('owner','editor','viewer') NOT NULL DEFAULT 'editor',
  joined_at BIGINT   NOT NULL,                       -- ms
  PRIMARY KEY (space_id, user_id),
  KEY ix_members_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS invites (
  code       CHAR(6)      NOT NULL,                  -- A-Z0-9 without 0/O/1/I
  space_id   CHAR(36)     NOT NULL,
  inviter_id CHAR(36)     NOT NULL,
  role       ENUM('editor','viewer') NOT NULL DEFAULT 'editor',
  expires_at DATETIME     NULL,                      -- NULL = never
  max_uses   INT UNSIGNED NULL,                      -- NULL = unlimited
  uses       INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME     NOT NULL,
  PRIMARY KEY (code),
  KEY ix_invites_space (space_id),
  KEY ix_invites_inviter (inviter_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Synced entities (one table per entity; same sync columns everywhere)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sp_transactions (
  id                CHAR(36)      NOT NULL,
  space_id          CHAR(36)      NOT NULL,
  type              ENUM('expense','income','transfer') NOT NULL DEFAULT 'expense',
  amount            DECIMAL(14,2) NOT NULL DEFAULT 0,
  currency          CHAR(3)       NULL,
  fx_rate           DECIMAL(14,6) NULL,              -- 1 unit of `currency` in space currency
  title             VARCHAR(255)  NULL,
  note              TEXT          NULL,
  category_id       CHAR(36)      NULL,
  date              DATE          NULL,
  time              TIME          NULL,
  payer_user_id     CHAR(36)      NULL,
  payment           VARCHAR(64)   NULL,              -- cash|card|bank|... free text
  split_type        ENUM('equal','exact','percent','shares','none') NOT NULL DEFAULT 'equal',
  splits            LONGTEXT      NULL,              -- JSON [{user_id, amount|percent|shares}]
  receipt_url       VARCHAR(512)  NULL,
  tags              LONGTEXT      NULL,              -- JSON ["food","trip"]
  location          VARCHAR(255)  NULL,
  recurring_rule_id CHAR(36)      NULL,
  created_by        CHAR(36)      NOT NULL,
  updated_by        CHAR(36)      NOT NULL,
  updated_at        BIGINT        NOT NULL,          -- ms, server-assigned
  client_updated_at BIGINT        NOT NULL DEFAULT 0,
  version           INT UNSIGNED  NOT NULL DEFAULT 1,
  deleted           TINYINT(1)    NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_tx_sync (space_id, updated_at),
  KEY ix_tx_date (space_id, deleted, date),
  KEY ix_tx_payer (space_id, payer_user_id),
  KEY ix_tx_category (space_id, category_id),
  KEY ix_tx_rule (recurring_rule_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sp_categories (
  id                CHAR(36)     NOT NULL,
  space_id          CHAR(36)     NOT NULL,
  name              VARCHAR(80)  NOT NULL,
  icon              VARCHAR(64)  NULL,
  color             VARCHAR(16)  NULL,
  type              ENUM('expense','income','both') NOT NULL DEFAULT 'expense',
  sort_order        INT          NOT NULL DEFAULT 0,
  parent_id         CHAR(36)     NULL,
  created_by        CHAR(36)     NOT NULL,
  updated_by        CHAR(36)     NOT NULL,
  updated_at        BIGINT       NOT NULL,
  client_updated_at BIGINT       NOT NULL DEFAULT 0,
  version           INT UNSIGNED NOT NULL DEFAULT 1,
  deleted           TINYINT(1)   NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_cat_sync (space_id, updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sp_budgets (
  id                CHAR(36)      NOT NULL,
  space_id          CHAR(36)      NOT NULL,
  name              VARCHAR(80)   NULL,
  category_id       CHAR(36)      NULL,              -- NULL = overall budget
  amount            DECIMAL(14,2) NOT NULL DEFAULT 0,
  currency          CHAR(3)       NULL,
  period            ENUM('weekly','monthly','yearly','custom') NOT NULL DEFAULT 'monthly',
  start_date        DATE          NULL,
  end_date          DATE          NULL,
  rollover          TINYINT(1)    NOT NULL DEFAULT 0,
  alert_80          TINYINT(1)    NOT NULL DEFAULT 1,
  alert_100         TINYINT(1)    NOT NULL DEFAULT 1,
  created_by        CHAR(36)      NOT NULL,
  updated_by        CHAR(36)      NOT NULL,
  updated_at        BIGINT        NOT NULL,
  client_updated_at BIGINT        NOT NULL DEFAULT 0,
  version           INT UNSIGNED  NOT NULL DEFAULT 1,
  deleted           TINYINT(1)    NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_budget_sync (space_id, updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sp_settlements (
  id                CHAR(36)      NOT NULL,
  space_id          CHAR(36)      NOT NULL,
  from_user_id      CHAR(36)      NOT NULL,          -- who paid
  to_user_id        CHAR(36)      NOT NULL,          -- who received
  amount            DECIMAL(14,2) NOT NULL DEFAULT 0,
  currency          CHAR(3)       NULL,
  date              DATE          NULL,
  note              TEXT          NULL,
  payment           VARCHAR(64)   NULL,
  created_by        CHAR(36)      NOT NULL,
  updated_by        CHAR(36)      NOT NULL,
  updated_at        BIGINT        NOT NULL,
  client_updated_at BIGINT        NOT NULL DEFAULT 0,
  version           INT UNSIGNED  NOT NULL DEFAULT 1,
  deleted           TINYINT(1)    NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_settle_sync (space_id, updated_at),
  KEY ix_settle_users (space_id, from_user_id, to_user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sp_comments (
  id                CHAR(36)     NOT NULL,
  space_id          CHAR(36)     NOT NULL,
  transaction_id    CHAR(36)     NOT NULL,
  user_id           CHAR(36)     NULL,               -- author (defaults to created_by in the app)
  text              TEXT         NOT NULL,
  created_by        CHAR(36)     NOT NULL,
  updated_by        CHAR(36)     NOT NULL,
  updated_at        BIGINT       NOT NULL,
  client_updated_at BIGINT       NOT NULL DEFAULT 0,
  version           INT UNSIGNED NOT NULL DEFAULT 1,
  deleted           TINYINT(1)   NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_comment_sync (space_id, updated_at),
  KEY ix_comment_tx (transaction_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sp_recurring_rules (
  id                CHAR(36)      NOT NULL,
  space_id          CHAR(36)      NOT NULL,
  title             VARCHAR(255)  NULL,
  type              ENUM('expense','income','transfer') NOT NULL DEFAULT 'expense',
  amount            DECIMAL(14,2) NOT NULL DEFAULT 0,
  currency          CHAR(3)       NULL,
  category_id       CHAR(36)      NULL,
  frequency         ENUM('daily','weekly','monthly','yearly') NOT NULL DEFAULT 'monthly',
  interval_n        INT UNSIGNED  NOT NULL DEFAULT 1, -- every N periods
  start_date        DATE          NULL,
  end_date          DATE          NULL,
  next_run          DATE          NULL,
  payer_user_id     CHAR(36)      NULL,
  payment           VARCHAR(64)   NULL,
  split_type        ENUM('equal','exact','percent','shares','none') NOT NULL DEFAULT 'equal',
  splits            LONGTEXT      NULL,
  note              TEXT          NULL,
  active            TINYINT(1)    NOT NULL DEFAULT 1,
  created_by        CHAR(36)      NOT NULL,
  updated_by        CHAR(36)      NOT NULL,
  updated_at        BIGINT        NOT NULL,
  client_updated_at BIGINT        NOT NULL DEFAULT 0,
  version           INT UNSIGNED  NOT NULL DEFAULT 1,
  deleted           TINYINT(1)    NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY ix_rule_sync (space_id, updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Activity feed
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS activity (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  space_id   CHAR(36)    NOT NULL,
  user_id    CHAR(36)    NULL,
  kind       VARCHAR(40) NOT NULL,                   -- transaction_added, member_joined, settlement_added, ...
  entity     VARCHAR(32) NULL,
  entity_id  CHAR(36)    NULL,
  data       LONGTEXT    NULL,                       -- JSON snapshot (title, amount, ...)
  created_at BIGINT      NOT NULL,                   -- ms
  PRIMARY KEY (id),
  KEY ix_activity_feed (space_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Caches / limits
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS fx_rates (
  base       CHAR(3)  NOT NULL,                      -- only 'USD' is stored; other bases are derived
  rates      LONGTEXT NOT NULL,                      -- JSON {"EUR":0.92,...}
  fetched_at DATETIME NOT NULL,
  PRIMARY KEY (base)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (
  rl_key       VARCHAR(191) NOT NULL,                -- e.g. otp:email:a@b.c, ip:1.2.3.4, ai:receipt:<uid>
  window_start INT UNSIGNED NOT NULL,                -- floor(unix_time / window_seconds)
  count        INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (rl_key, window_start),
  KEY ix_rl_window (window_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ai_usage (
  id      BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id CHAR(36)     NOT NULL,
  day     DATE         NOT NULL,
  kind    VARCHAR(16)  NOT NULL,                     -- receipt | ask
  count   INT UNSIGNED NOT NULL DEFAULT 0,
  tokens  INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_ai_usage (user_id, day, kind),
  KEY ix_ai_day (day)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
